func (q *Queries) RestartPayment(ctx context.Context, arg RestartPaymentParams) (Payment, error) {
	row := q.db.QueryRow(ctx, restartPayment, arg.ProviderOrderID, arg.ApproveUrl, arg.OrderID)
	var i Payment
	err := row.Scan(
		&i.ID,
		&i.OrderID,
		&i.Provider,
		&i.ProviderOrderID,
		&i.ApproveUrl,
		&i.Status,
		&i.CaptureID,
		&i.AmountCents,
		&i.Currency,
		&i.CapturedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.RefundRequestedAt,
		&i.RefundID,
		&i.RefundedAt,
		&i.RefundAttempts,
		&i.RefundLastError,
		&i.RefundRetryAt,
	)
	return i, err
}
